{"version": 4, "nodes": [{"type": "group", "title": "Диспетчерская склада", "frame": "plain", "columns": 12, "items": [{"type": "html", "span": 12, "height": 780, "allowServices": ["WarehouseDispatchService"], "css": "*{box-sizing:border-box}
body{margin:0;font:13px/1.4 var(--mantine-font-family,-apple-system,Segoe UI,Roboto,sans-serif);color:var(--mantine-color-text);background:var(--mantine-color-body)}
#wd{padding:12px}
h3{margin:14px 0 6px;font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:var(--mantine-color-dimmed)}
.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}
.kpi{background:var(--mantine-color-default);border:1px solid var(--mantine-color-default-border);border-radius:10px;padding:10px 12px}
.kpi .v{font-size:22px;font-weight:700;line-height:1.1}
.kpi .l{font-size:11px;color:var(--mantine-color-dimmed);margin-top:2px}
.kpi.warn .v{color:var(--mantine-color-red-6)}
.cols{display:grid;grid-template-columns:1.6fr 1fr;gap:14px;margin-top:6px}
.zoneblock{margin-bottom:10px}
.zoneblock .zh{display:flex;justify-content:space-between;font-weight:600;margin-bottom:4px}
.grid{display:flex;flex-wrap:wrap;gap:4px}
.cellt{width:46px;height:40px;border-radius:6px;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:10px;color:#0f172a;border:1px solid var(--mantine-color-default-border);cursor:default;overflow:hidden}
.cellt b{font-weight:700;font-size:11px}
.cellt small{font-size:9px;opacity:.75}
.zbar{margin-bottom:6px}
.zbar .t{display:flex;justify-content:space-between;font-size:12px;margin-bottom:2px}
.zbar .track{height:8px;border-radius:5px;background:var(--mantine-color-default-border);overflow:hidden}
.zbar .fill{height:100%;border-radius:5px}
.badge{display:inline-block;padding:3px 9px;border-radius:20px;font-size:12px;font-weight:600;margin:0 6px 6px 0}
.hint{background:var(--mantine-color-default);border:1px solid var(--mantine-color-default-border);border-left:3px solid var(--mantine-color-yellow-6);border-radius:8px;padding:7px 10px;margin-bottom:6px;font-size:12px}
.hint.ok{border-left-color:var(--mantine-color-green-6)}
.hint.crit{border-left-color:var(--mantine-color-red-6)}
.feed{background:var(--mantine-color-default);border:1px solid var(--mantine-color-default-border);border-radius:10px;max-height:190px;overflow:auto}
.feed .r{display:flex;gap:10px;align-items:center;padding:5px 10px;border-bottom:1px solid var(--mantine-color-default-border);font-size:12px}
.feed .r:last-child{border-bottom:0}
.feed .dir{font-weight:700;width:14px;text-align:center}
.feed .in{color:var(--mantine-color-green-6)}.feed .out{color:var(--mantine-color-red-6)}
.feed .tm{color:var(--mantine-color-dimmed);font-variant-numeric:tabular-nums}
.feed .q{margin-left:auto;font-weight:700;font-variant-numeric:tabular-nums}
#status{margin-top:8px;font-size:11px;color:var(--mantine-color-dimmed)}
.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--mantine-color-green-6);margin-right:5px;vertical-align:middle}
.empty{color:var(--mantine-color-dimmed);padding:8px}
", "html": "<div id="wd">
  <div id="kpis" class="kpis"></div>
  <div class="cols">
    <div>
      <h3>Карта загрузки склада (хитмап ячеек)</h3>
      <div id="map"><div class="empty">нет данных</div></div>
    </div>
    <div>
      <h3>Нагрузка по зонам</h3>
      <div id="zones"><div class="empty">—</div></div>
      <h3>Очередь задач (бэклог)</h3>
      <div id="backlog"></div>
      <h3>Подсказки по оптимизации</h3>
      <div id="hints"></div>
    </div>
  </div>
  <h3>Последние движения</h3>
  <div id="feed" class="feed"><div class="empty">нет движений</div></div>
  <div id="status"><span class="dot"></span><span id="stxt">подключение…</span></div>
</div>
", "js": "var $=function(id){return document.getElementById(id)};
function n(x){x=Number(x||0);return (Math.round(x*100)/100).toString()}
function utilColor(u){ // u = percent number or null
  if(u==null) return 'var(--mantine-color-default-border)';
  if(u<=0) return 'var(--mantine-color-default-border)';
  if(u<50) return '#86efac';
  if(u<80) return '#fde047';
  if(u<95) return '#fb923c';
  return '#ef4444';
}
function hhmmss(d){ try{var t=new Date(d);return t.toLocaleTimeString();}catch(e){return ''} }

function render(b){
  b=b||{}; var k=b.kpis||{};
  // KPIs
  var kp=[
    ['Приход (смена)', n(k.inQty), false],
    ['Расход (смена)', n(k.outQty), false],
    ['Открытых задач', (k.openTasks||0), (k.openTasks||0)>0],
    ['Занято ячеек', (k.cellsOccupied||0)+' / '+(k.cellsTotal||0), false],
    ['Средняя загрузка', (k.avgUtil==null?'—':k.avgUtil+'%'), (k.avgUtil||0)>=90]
  ];
  $('kpis').innerHTML=kp.map(function(x){return '<div class="kpi'+(x[2]?' warn':'')+'"><div class="v">'+x[1]+'</div><div class="l">'+x[0]+'</div></div>'}).join('');

  // Heatmap — cells grouped by zone, sorted by address
  var cells=(b.cells||[]).slice().sort(function(a,c){return (a.line-c.line)||(a.rack-c.rack)||(a.shelf-c.shelf)||(a.cell-c.cell)});
  var byZone={};
  cells.forEach(function(c){var z=c.zone||'—';(byZone[z]=byZone[z]||[]).push(c)});
  var zk=Object.keys(byZone);
  $('map').innerHTML = zk.length? zk.map(function(z){
    var tiles=byZone[z].map(function(c){
      var col=utilColor(c.util);
      var lab=(c.util==null? n(c.occ): c.util+'%');
      var tip=c.name+' — занято '+n(c.occ)+(c.cap>0?(' / '+n(c.cap)):'')+(c.util!=null?(' ('+c.util+'%)'):'');
      return '<div class="cellt" title="'+tip+'" style="background:'+col+'"><b>'+(c.name||'')+'</b><small>'+lab+'</small></div>';
    }).join('');
    return '<div class="zoneblock"><div class="zh"><span>'+z+'</span></div><div class="grid">'+tiles+'</div></div>';
  }).join(''):'<div class="empty">ячейки не заведены</div>';

  // Zone load bars (busiest first)
  var zones=b.zones||[];
  $('zones').innerHTML = zones.length? zones.map(function(z){
    var u=z.util==null?0:z.util; var col=utilColor(z.util);
    return '<div class="zbar"><div class="t"><span>'+(z.name||'—')+'</span><span>'+(z.util==null?'—':z.util+'%')+' · оборот '+n(z.throughput)+'</span></div><div class="track"><div class="fill" style="width:'+Math.min(100,u)+'%;background:'+col+'"></div></div></div>';
  }).join(''):'<div class="empty">—</div>';

  // Backlog
  var pa=k.putawayBacklog||0, pk=k.pickBacklog||0;
  $('backlog').innerHTML=
    '<span class="badge" style="background:'+(pa>0?'var(--mantine-color-red-light)':'var(--mantine-color-green-light)')+';color:'+(pa>0?'var(--mantine-color-red-light-color)':'var(--mantine-color-green-light-color)')+'">Приёмка (put-away): '+pa+'</span>'+
    '<span class="badge" style="background:'+(pk>0?'var(--mantine-color-red-light)':'var(--mantine-color-green-light)')+';color:'+(pk>0?'var(--mantine-color-red-light-color)':'var(--mantine-color-green-light-color)')+'">Отбор (pick): '+pk+'</span>';

  // Optimization hints
  var hints=[];
  zones.forEach(function(z){ if(z.util!=null && z.util>=90) hints.push(['crit','Зона «'+z.name+'» переполнена ('+z.util+'%) — перебалансировать или разгрузить']); });
  (b.cells||[]).forEach(function(c){ if(c.cap>0 && c.occ>c.cap) hints.push(['crit','Ячейка «'+c.name+'» сверх вместимости ('+n(c.occ)+' / '+n(c.cap)+')']); });
  if((k.openTasks||0)>0) hints.push(['','Очередь задач: '+k.openTasks+' (put-away '+pa+', pick '+pk+') — узкое место']);
  var busy=zones.slice().sort(function(a,c){return c.throughput-a.throughput})[0];
  if(busy && busy.throughput>0) hints.push(['','Пиковая нагрузка: зона «'+busy.name+'» (оборот '+n(busy.throughput)+')']);
  if(!hints.length) hints.push(['ok','Всё в норме — заторов и переполнений нет']);
  $('hints').innerHTML=hints.slice(0,6).map(function(h){return '<div class="hint '+h[0]+'">'+h[1]+'</div>'}).join('');

  // Feed
  var rec=b.recent||[];
  $('feed').innerHTML= rec.length? rec.map(function(m){
    var inn=m.dir==='in';
    return '<div class="r"><span class="tm">'+hhmmss(m.date)+'</span><span class="dir '+(inn?'in':'out')+'">'+(inn?'▲':'▼')+'</span><span>'+(m.item||'')+'</span><span style="color:var(--mantine-color-dimmed)">'+(m.cell||'')+'</span><span class="q '+(inn?'in':'out')+'">'+(inn?'+':'')+n(m.qty)+'</span></div>';
  }).join(''):'<div class="empty">нет движений</div>';

  $('stxt').textContent='обновлено '+new Date().toLocaleTimeString();
}

var busy=false;
async function tick(){
  if(busy) return; busy=true;
  try{ var b=await ZuloForm.callService('WarehouseDispatchService','GetDispatchBoard',{}); render(b); }
  catch(e){ $('stxt').textContent='нет связи с сервером'; }
  finally{ busy=false; }
}
tick();
setInterval(tick, 2500);
// если мост поддерживает подписку на таблицу — обновляемся мгновенно по пушу движения
try{ if(ZuloForm.subscribeTable){ ZuloForm.subscribeTable('TR_Stock', tick); ZuloForm.subscribeTable('TB_Stock', tick); } }catch(e){}
"}]}]}
